n25225.content:
\begin{lemma}[Marcinkiewicz-Zygmund inequality]
\label{mzi}
\lean{Real.marcinkiewicz_zygmund', Real.marcinkiewicz_zygmund}
\leanok
Let $m\geq 1$. If $f:G\to\mathbb{R}$ is such that $\mathbb{E}_x f(x)=0$ and $\left\lvert f(x)\right\rvert\leq 2$ for all $x$ then
\[\mathbb{E}_{x_1,\ldots,x_n} \left\lvert \sum_{i=1}^n f(x_i)\right\rvert^{2m} \leq (4mn)^{m}.\]
\end{lemma}

n25227.content:
\begin{lemma}[Complex-valued Marcinkiewicz-Zygmund inequality]
\label{mzi_complex}
\leanok
\lean{RCLike.marcinkiewicz_zygmund}
Let $m\geq 1$. If $f:G\to\mathbb{C}$ is such that $\mathbb{E}_x f(x)=0$ and $\left\lvert f(x)\right\rvert\leq 2$ for all $x$ then
\[\mathbb{E}_{x_1,\ldots,x_n} \left\lvert \sum_{i=1}^n f(x_i)\right\rvert^{2m} \leq (8mn)^{m}.\]
\end{lemma}

n25229.content:
\begin{lemma}
  \label{random_approx_expect}
  \lean{AlmostPeriodicity.lemma28}
  \leanok

  Let $\epsilon>0$ and $m\geq 1$. Let $A\subseteq G$ and $f:G\to \mathbb{C}$.
  If $k\geq 64m\epsilon^{-2}$ then the set
  \[
    L = \{\tup{a}\in A^k : \|\tfrac{1}{k}\sum_{i=1}^k f(x-a_i)-\mu_A\ast f\|_{2m}
      \le \epsilon \| f\|_{2m}\}.
  \]
  has size at least $\lvert A \rvert^k/2$.
\end{lemma}

n25230.content:
\begin{proof}
\uses{mzi_complex}
\leanok
Note that if $a\in A$ is chosen uniformly at random then, for any fixed $x\in G$,
\[\mathbb{E}f(x-a_i)= \frac{1}{\left\lvert A\right\rvert}\sum_{a\in A}f(x-a)=\frac{1}{\left\lvert A\right\rvert}1_{A}\ast f(x)=\mu_A\ast f(x).\]
Therefore, if we choose $a_1,\ldots,a_k\in A$ independently uniformly at random, for any fixed $x\in G$ and $1\leq i\leq k$,  the random variable $f(x-a_i)-f\ast \mu_A(x)$ has mean zero. By the Marcinkiewicz-Zygmund inequality Lemma~\ref{mzi}, therefore,
\begin{multline*}
\mathbb{E}\left\lvert  \frac{1}{k}\sum_i f(x-a_i)-f\ast \mu_A(x)\right\rvert^{2m} \leq \\(16m/k)^mk^{-1} \mathbb{E}\sum_i \left\lvert f(x-a_i)-f\ast \mu_A(x)\right\rvert^{2m}.
\end{multline*}
We now sum both sides over all $x\in G$. By the triangle inequality, for any fixed $1\leq i\leq k$ and $a_i\in A$,
\begin{align*}
\sum_{x\in G} \left\lvert f(x-a_i)-f\ast \mu_A(x)\right\rvert^{2m}
&\leq 2^{2m-1}\sum_{x\in G}\left\lvert f(x-a_i)\right\rvert^{2m}+\sum_{x\in G}\left\lvert f\ast \mu_A(x)\right\rvert^{2m}\\
&\leq 2^{2m-1}\left( \lVert f\rVert_{2m}^{2m}+\lVert f\ast \mu_A\rVert_{2m}^{2m}\right).
\end{align*}
We note that $\lVert \mu_A\rVert_1=\frac{1}{\left\lvert A\right\rvert}\sum_{x\in A}1_{A}(x)=\left\lvert A\right\rvert/\left\lvert A\right\rvert=1$, and hence by Young's inequality, $\lVert f\ast \mu_A\rVert_{2m}\leq \lVert f\rVert_{2m}$, and so
\[\sum_{x\in G} \left\lvert f(x-a_i)-f\ast \mu_A(x)\right\rvert^{2m}\leq 2^{2m}\lVert f\rVert_{2m}^{2m}.\]
It follows that
\[\mathbb{E}_{a_1,\ldots,a_k\in A}\lVert \frac{1}{k}\sum_i\tau_{a_i}f-f\ast \mu_A\rVert_{2m}^{2m}\leq
(64m/k)^m\lVert f\rVert_{2m}^{2m}.\]
In particular, if $k\geq 64\epsilon^{-2}m$ then the right-hand side is at most $(\frac{\epsilon}{2}\lVert f\rVert_{2m})^{2m}$ as required.
\end{proof}

n25231.content:
\begin{lemma}
  \label{aps_in_translates}
  \lean{AlmostPeriodicity.just_the_triangle_inequality}
  \leanok

  Let $A\subseteq G$ and $f:G\to \mathbb{C}$. Let $\epsilon>0$ and $m\geq 1$ and $k\geq 1$. Let
  \[
    L = \{\tup{a}\in A^k : \|\tfrac{1}{k}\sum_{i=1}^k f(x-a_i) - \mu_A\ast f\|_{2m}
      \leq \epsilon \| f\|_{2m}\}.
  \]
  If $t\in G$ is such that $\tup{a}\in L$ and $\tup{a}+(t,\ldots,t)\in L$ then
  \[\| \tau_t(\mu_A\ast f)-\mu_A\ast f\|_{2m}\leq 2\epsilon \|f\|_{2m}.\]
\end{lemma}

n25233.content:
\begin{lemma}
\label{lots_of_diagonals}
\lean{big_shifts}
\leanok
Let $A\subseteq G$ and $k\geq 1$ and $L\subseteq A^k$. Then there exists some $\tup{a}\in L$ such that
\[\#\{ t\in G : \tup{a}+(t,\ldots,t)\in L\}\geq \frac{\lvert L\rvert}{\lvert A+S\rvert^k}\lvert S\rvert.\]
\end{lemma}

n25235.content:
\begin{theorem}[$L_p$ almost periodicity]
\label{lp_ap}
\lean{AlmostPeriodicity.almost_periodicity}
\leanok
Let $\epsilon\in (0,1]$ and $m\geq 1$. Let $K\geq 2$ and $A,S\subseteq G$ with $\lvert A+S\rvert\leq K\lvert A\rvert$.
Let $f:G\to \mathbb{C}$. There exists $T\subseteq G$ such that
\[\lvert T\rvert \geq K^{-512m\epsilon^{-2}}\lvert S\rvert\]
such that for any $t\in T$ we have
\[\| \tau_t(\mu_A\ast f)-\mu_A\ast f\|_{2m}\leq \epsilon \| f\|_{2m}.\]
\end{theorem}

n25237.content:
\begin{theorem}[$L_\infty$ almost periodicity]
\label{linfty_ap}
\lean{AlmostPeriodicity.linfty_almost_periodicity}
\leanok
Let $\epsilon\in (0,1]$. Let $K\geq 2$ and $A,S\subseteq G$ with $\lvert A+S\rvert\leq K\lvert A\rvert$.
Let $B,C\subseteq G$. Let $\eta=\min(1,\lvert C\rvert/\lvert B\rvert)$. There exists $T\subseteq G$ such that
\[\lvert T\rvert \geq K^{-4096\lceil \mathcal{L}{\eta}\rceil\epsilon^{-2}}\lvert S\rvert\]
such that for any $t\in T$ we have
\[\| \tau_t(\mu_A\ast 1_B\ast \mu_C)-\mu_A\ast 1_B\ast \mu_C\|_{\infty}\leq \epsilon.\]
\end{theorem}

n25239.content:
\begin{theorem}
\label{linfty_ap_boosted}
\lean{AlmostPeriodicity.linfty_almost_periodicity_boosted}
\leanok
Let $\epsilon\in (0,1]$ and $k\geq 1$. Let $K\geq 2$ and $A,S\subseteq G$ with $\lvert A+S\rvert\leq K\lvert A\rvert$.
Let $B,C\subseteq G$. Let $\eta=\min(1,\lvert C\rvert/\lvert B\rvert)$. There exists $T\subseteq G$ such that
\[\lvert T\rvert \geq K^{-4096\lceil \mathcal{L}{\eta}\rceil k^2\epsilon^{-2}}\lvert S\rvert\]
such that
\[\| \mu_T^{(k)}\ast \mu_A\ast 1_B\ast \mu_C-\mu_A\ast 1_B\ast \mu_C\|_{\infty}\leq \epsilon.\]
\end{theorem}

n25241.content:
\begin{definition}[Dissociation]
\label{dissociated}
\lean{AddDissociated}
\leanok
We say that $A\subseteq G$ is dissociated if, for any $m\geq 1$, and any $x\in G$, there is at most one $A'\subset A$ of size $\left\lvert A'\right\rvert=m$ such that
\[\sum_{a\in A'}a=x.\]
\end{definition}

n25242.content:
\begin{lemma}[Rudin's exponential inequality]
\label{rudin_exp}
\uses{dissociated}
\lean{rudin_exp_ineq}
\leanok
If the discrete Fourier transform of $f : G \longrightarrow \mathbb{C}$ has dissociated support, then
$$
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
\exp(\Re f) \le \exp\left(\frac{\lVert f\rVert_2^2}2\right)$$
It follows that
\[
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
_x e^{\left\lvert f(x)\right\rvert} \le 2e^{\| f\|_2^2/2}.\]
\end{lemma}

n25243.content:
\begin{proof}
\uses{mzi_complex}
\leanok
Using the convexity of $t\mapsto e^{tx}$ (for all $x\geq 0$ and $t\in[-1,1]$) we have
\[e^{tx}\le \cosh(x)+t\sinh(x).\]
It follows (taking $x=\lvert z\rvert$ and $t=\Re(z)/\lvert z\rvert$) that, for any $z\in \mathbb{C}$,
\[e^{\Re z}\le \cosh \lvert z\rvert +\Re(z/\lvert z\rvert)\sinh \lvert z\rvert.\]
In particular, if $c_\gamma\in \mathbb{C}$ with $\lvert c_\gamma\rvert=1$ is such that $\widehat{f}(\gamma)=c_\gamma\lvert \widehat{f}(\gamma)\rvert$, then
\begin{align*}
e^{\Re f(x)}
&= \exp\left( \Re \sum_{\gamma\in\Gamma}\widehat{f}(\gamma)\gamma(x)\right)\\
&=\prod_{\gamma\in \Gamma} \exp\left( \Re \widehat{f}(\gamma)\gamma(x)\right)\\
&\le \prod_{\gamma\in \Gamma}\left( \cosh \lvert \widehat{f}(\gamma)\rvert +\Re c_\gamma \gamma(x)\sinh \lvert \widehat{f}(\gamma)\rvert\right).
\end{align*}
Therefore
\[
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
_x e^{\Re f(x)}\le 
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
_x \prod_{\gamma\in \Gamma} \left( \cosh\lvert \widehat{f}(\gamma)\rvert+\Re c_\gamma \gamma(x)\sinh\lvert \widehat{f}(\gamma)\rvert\right).\]
Using $\Re z=(z+\overline{z})/2$ the product here can be expanded as the sum of
\[\prod_{\gamma\in \Gamma_2}\frac{c_\gamma}{2}\prod_{\gamma\in \Gamma_3}\frac{\overline{c_\gamma}}{2}\left(\prod_{\gamma\in \Gamma_1}\cosh\lvert \widehat{f}(\gamma)\rvert\right)\left(\prod_{\gamma\in \Gamma_2\cup\Gamma_3}\sinh\lvert \widehat{f}(\gamma)\rvert\right)\left(\sum_{\gamma\in \Gamma_2}\gamma-\sum_{\lambda\in \Gamma_3}\lambda\right)(x)\]
as $\Gamma_1\sqcup \Gamma_2\sqcup \Gamma_3=\Gamma$ ranges over all partitions of $\Gamma$ into three disjoint parts. Using the definition of dissociativity we see that
\[\sum_{\gamma\in \Gamma_2}\gamma-\sum_{\lambda\in \Gamma_3}\lambda\neq 0\]
unless $\Gamma_2=\Gamma_3=\emptyset$. In particular summing this term over all $x\in G$ gives $0$. Therefore the only term that survives averaging over $x$ is when $\Gamma_1=\Gamma$, and so
\[
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
_x e^{\Re f(x)}\le \prod_{\gamma\in \Gamma} \cosh \lvert \widehat{f}(\gamma)\rvert.\]
The conclusion now follows using $\cosh(x) \le e^{x^2/2}$ and $\sum_{\gamma\in \Gamma}\lvert \widehat{f}(\gamma)\rvert^2=\| f\|_2^2$. The second conclusion follows by applying it to $f(x)$ and $-f(x)$ and using
\[e^{\left\lvert y\right\rvert}\le e^y+e^{-y}.\]
\end{proof}

n25244.content:
\begin{lemma}[Rudin's inequality]
\label{rudin}
\uses{dissociated}
\lean{rudin_ineq}
\leanok
If the discrete Fourier transform of $f : G \longrightarrow \mathbb{C}$ has dissociated support and $p \ge 2$ is an integer, then $\lVert f\rVert_p \le 4\sqrt{pe} \lVert f\rVert_2$.
\end{lemma}

n25245.content:
\begin{proof}
\uses{rudin_exp}
\leanok
It is enough to show that $\lVert \Re f\rVert_p \le 2\sqrt{pe} \lVert f\rVert_2$ as then
$$\lVert f\rVert_p \le \lVert \Re f\rVert_p + \lVert i \Im f\rVert_p = \lVert \Re f\rVert_p + \lVert \Re (-if)\rVert_p \le 4\sqrt{pe} \lVert f\rVert_2$$

If $f = 0$, the result is obvious. So assume $f \ne 0$. $\lVert f\rVert_2 > 0$, so WLOG $\lVert f\rVert_2 = \sqrt p$.

Rudin's exponential inequality for $f$ becomes $
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
\exp|\Re f| \le 2\exp(\frac p2) = (2\sqrt e)^p$. Using $\frac{x^p}{p!} \le e^x$ for positive $x$, we get
$$\frac{\lVert \Re f\rVert_p^p}{p^p} \le \frac{\lVert \Re f\rVert_p^p}{p!} = 
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
\frac{|\Re f|^p}{p!} \le 
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
\exp|\Re f|$$
Rearranging, $\lVert \Re f\rVert_p \le 2 p\sqrt{e} = 2 \sqrt{pe} \lVert f\rVert_2$.
% TODO: Normalisation issue
\end{proof}

n25246.content:
\begin{definition}[Large spectrum]
  \label{large_spec}
  \lean{largeSpec}
  \leanok

  Let $G$ be a finite abelian group and $f:G\to\mathbb{C}$. Let $\eta\in \mathbb{R}$. The $\eta$-large spectrum is defined to be
  \[\Delta_\eta(f) = \{ \gamma\in\widehat{G} : \lvert \widehat{f}(\gamma)\rvert \geq \eta\lVert f\rVert_1\}.\]
\end{definition}

n25248.content:
\begin{definition}[Energy]
\label{energy}
\uses{weight_energy}
\lean{boringEnergy}
\leanok
Let $G$ be a finite abelian group and $A\subseteq G$. Let $m\geq 1$. We define
\[E_{2m}(A)=\sum_{a_1,\ldots,a_{2m}\in A}1_{a_1+\cdots-a_{2m}=0}.\]
\end{definition}

n25249.content:
\begin{lemma}
\label{general_hoelder}
\uses{large_spec, weight_energy}
\lean{general_hoelder}
\leanok
Let $G$ be a finite abelian group and $f:G\to\mathbb{C}$. Let $\nu:G\to \mathbb{R}_{\geq 0}$ be such that whenever $\left\lvert f\right\rvert\neq 0$ we have $\nu \geq 1$. Let $\Delta\subseteq \Delta_\eta(f)$. Then, for any $m\geq 1$.
\[\eta^{2m}\frac{\lVert f\rVert_1^2}{\lVert f\rVert_2^2}\left\lvert \Delta\right\rvert^{2m}\le E_{2m}(\Delta;\nu).\]
\end{lemma}

n25251.content:
\begin{lemma}
\label{spec_hoelder}
\uses{energy}
\lean{spec_hoelder}
\leanok
Let $G$ be a finite abelian group and $f:G\to\mathbb{C}$. Let $\Delta\subseteq \Delta_\eta(f)$. Then, for any $m\geq 1$.
\[N^{-1}\eta^{2m}\frac{\lVert f\rVert_1^2}{\lVert f\rVert_2^2}\left\lvert \Delta\right\rvert^{2m}\le E_{2m}(\Delta).\]
\end{lemma}

n25252.content:
\begin{proof}
\uses{general_hoelder}
\leanok
Apply Lemma~\ref{general_hoelder} with $\nu\equiv 1$, and use the fact that $\sum_x \lambda(x)$ is $N$ if $\lambda\equiv 1$ and $0$ otherwise.
\end{proof}

n25255.content:
\begin{lemma}
\label{diss_energy}
\uses{dissociated, energy}
\lean{AddDissociated.boringEnergy_le}
\leanok
If $A\subseteq G$ is dissociated then $E_{2m}(A) \le (32e m \left\lvert A\right\rvert)^m$.
\end{lemma}

n25256.content:
\begin{proof}
\uses{energy_alt, rudin}
\leanok
By Lemma~\ref{energy_alt} and Lemma~\ref{rudin}
\begin{align*}
  E_{2m}(A)
  & = 
  \mathop{
    \mathchoice{\vcenter{\hbox{\larger[4]$\mathbb{E}$}}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
               {\kern0pt\mathbb{E}}
  }\displaylimits
_\gamma \left\lvert \hat 1_A(\gamma)\right\rvert^{2m} \\
  & = \lVert \hat 1_A\rVert_{2m}^{2m} \\
  & \le (4\sqrt{2em})^{2m} \lVert \hat 1_A\rVert_2^{2m} \\
  & = (32em)^m \lVert 1_A\rVert_2^{2m} \\
  & = (32em)^m \left\lvert A\right\rvert^m
\end{align*}
\end{proof}

n25257.content:
\begin{lemma}
  \label{diss_span}
  \uses{dissociated}
  \lean{Finset.exists_subset_addSpan_card_le_of_forall_addDissociated}
  \leanok

  If $A\subseteq G$ contains no dissociated set with $\geq K+1$ elements,
  then there is $A'\subseteq A$ of size $\left\lvert A'\right\rvert\le K$ such that
  \[A\subseteq \left\{ \sum_{a\in A'}c_aa : c_a\in \{-1,0,1\} \right\}.\]
\end{lemma}

n25259.content:
\begin{theorem}[Chang's lemma]
\label{chang}
\uses{large_spec}
\lean{chang}
\leanok
Let $G$ be a finite abelian group and $f:G\to \mathbb{C}$. Let $\eta >0$ and $\alpha=N^{-1}\lVert f\rVert_1^2/\lVert f\rVert_2^2$. There exists some $\Delta\subseteq \Delta_\eta(f)$ such that
\[\left\lvert \Delta\right\rvert\le \lceil e\mathcal{L}(\alpha)\eta^{-2}\rceil \]
and
\[\Delta_\eta(f)\subseteq \left\{ \sum_{\gamma\in\Delta}c_\gamma \gamma : c_\gamma\in \{-1,0,1\} \right\}.\]
\end{theorem}

n25261.content:
\begin{lemma}
