n25263.content:
\begin{lemma}
\label{unbalancing}
\lean{unbalancing}
\leanok
Let $\epsilon\in(0,1)$ and $\nu:G\to\mathbb{R}_{\geq 0}$ be some probability measure such that $\widehat{\nu}\geq 0$. Let $f:G\to\mathbb{R}$. If $\lVert f\circ f\rVert_{p(\nu)}\geq \epsilon$ for some $p\geq 1$ then $\lVert f\circ f+1\rVert_{p'(\nu)}\geq 1+\tfrac{1}{2}\epsilon$ for $p'=120\epsilon^{-1}\log(3/\epsilon)$.
\end{lemma}

n25265.content:
\begin{lemma}
\label{drc}
\lean{drc}
\leanok
Let $p\geq 2$ be an even integer. Let $B_1,B_2\subseteq G$ and $\mu=\mu_{B_1}\circ\mu_{B_2}$. For any finite set $A\subseteq G$ and function $f:G\to\mathbb{R}_{\geq 0}$ there exist $A_1\subseteq B_1$ and $A_2\subseteq B_2$ such that
\[\langle \mu_{A_1}\circ \mu_{A_2}, f\rangle \lVert 1_{A}\circ 1_{A}\rVert_{p(\mu)}^p\leq 2\langle (1_{A}\circ 1_{A})^p,f\rangle_\mu\]
and
\[\min\left( \frac{\left\lvert A_1\right\rvert}{\left\lvert B_1\right\rvert},\frac{\left\lvert A_2\right\rvert}{\left\lvert B_2\right\rvert}\right)\geq \frac{1}{4}\left\lvert A\right\rvert^{-2p}\lVert 1_{A}\circ 1_{A}\rVert_{p(\mu)}^{2p}.\]
\end{lemma}

n25267.content:
\begin{lemma}
\label{sift}
\lean{sifting}
\leanok
Let $\epsilon,\delta >0$ and $p\geq \max(2,\epsilon^{-1}\log(2/\delta))$ be an even integer. Let $B_1,B_2\subseteq G$, and let $\mu=\mu_{B_1}\circ\mu_{B_2}$. For any finite set $A\subseteq G$, if
\[S=\{ x\in G: 1_{A}\circ 1_{A}(x)>(1-\epsilon)\lVert 1_{A}\circ 1_{A}\rVert_{p(\mu)}\},\]
then there are $A_1\subseteq B_1$ and $A_2\subseteq B_2$ such that
\[\langle \mu_{A_1}\circ\mu_{A_2},1_{S}\rangle \geq 1-\delta\]
and
\[\min\left( \frac{\left\lvert A_1\right\rvert}{\left\lvert B_1\right\rvert},\frac{\left\lvert A_2\right\rvert}{\left\lvert B_2\right\rvert}\right)\geq \frac{1}{4}\left\lvert A\right\rvert^{-2p}\lVert 1_{A}\circ 1_{A}\rVert_{p(\mu)}^{2p}.\]
\end{lemma}

n25269.content:
\begin{corollary}\label{sift_cor}
\lean{sifting_cor}
\leanok
Let $\epsilon,\delta>0$ and $p\geq \max(2,\epsilon^{-1}\log(2/\delta))$ be an even integer and $\mu\equiv 1/N$. If $A\subseteq G$ has density $\alpha$ and
\[S = \{ x : \mu_A\circ \mu_A(x) \geq (1-\epsilon)\| \mu_A\circ \mu_A\|_{p(\mu)}\}\]
then there are $A_1,A_2\subseteq G$ such that
\[\langle \mu_{A_1}\circ \mu_{A_2}, 1_S\rangle \geq 1-\delta\]
and both $A_1$ and $A_2$ have density
\[\geq \frac{1}{4}\alpha^{2p}.\]
\end{corollary}

n25270.content:
\begin{proof}
\uses{sift}
\leanok
We apply Lemma~\ref{sift} with $B_1=B_2=G$. It remains to note that
\[\| 1_A\circ 1_A\|_{p(\mu)}\geq \| 1_A\circ 1_A\|_{1(\mu)}=\lvert A\rvert^2/N.\]
\end{proof}

n25271.content:
\begin{theorem}
