n25279.content:
\begin{lemma}
\label{global_dichotomy}
\lean{global_dichotomy}
\leanok
Let $\epsilon >0$ and $\mu\equiv 1/N$. If $A,C\subseteq G$, where $C$ has density at least $\gamma$, and
\[\left\lvert N\langle \mu_A\ast \mu_A,\mu_C\rangle -1\right\rvert>\epsilon\]
then, if $f=(\mu_A-1/N)$, $\lVert f\circ f\rVert_{p(\mu)} \geq \epsilon /2N$ for $p=2\lceil \mathcal{L}{(}\gamma)\rceil$.
\end{lemma}

n25280.content:
\begin{proof}
\uses{ast_le_circ, ast_expand, circ_expand}
\leanok
By H\"{o}lder's inequality, for any $p\geq 1$
\[\epsilon < \left\lvert  N\langle \mu_A \ast \mu_A - 1/N, \mu_C \rangle \right\rvert \leq \lVert \mu_A\ast \mu_A-1/N\rVert_p\gamma^{-1/p}N^{1-1/p}.\]
In particular if we choose $p=2\lceil\mathcal{L}{(}\gamma)\rceil$ then $\gamma^{-1/p}\leq e^{1/2}\leq 2$ and so we deduce that, by Lemma~\ref{ast_expand},
\[\lVert f\ast f\rVert_{p}\geq \tfrac{1}{2}\epsilon N^{1/p-1}.\]
It remains to use Lemmas~\ref{ast_expand} and \ref{circ_expand} and apply Lemma~\ref{ast_le_circ}, and note that we can pass from the $L^p$ norm to the $L^p(\mu)$ norm losing a factor of $N^{1/p}$.
\end{proof}

