n25287.content:
\begin{definition}[Bohr sets]
\label{bohr-set}
\lean{BohrSet}
\leanok
Let $\nu: \widehat{G} \to \mathbb{R}$. The corresponding Bohr set is defined to be
\[\mathrm{Bohr}(\nu)=\left\{ x\in G : \left\lvert 1-\gamma(x)\right\rvert\leq \nu(\gamma)\textrm{ for all }\gamma\in\Gamma\right\}.\]
The rank of $\nu$, denoted by $\mathrm{rk}(\nu)$, is defined to be the size of the set of those $\gamma\in\widehat{G}$ such that $\nu(\gamma)<2$.

(Basic API facts: Bohr sets are symmetric and contain $0$. Also that, without loss of generality, we can assume $\nu$ takes only values in $\mathbb{R}_{\geq 0}$ - I think it might be easier to have the definition allow arbitrary real values, and then switch to non-negative only in proofs where convenient. Or could have the definition only allow non-negative valued functions in the first place.)
\end{definition}

n25290.content:
\begin{definition}[Regularity]
\label{bohr-reg-def}
\uses{bohr-set}
\lean{BohrSet.IsRegular}
\leanok
We say $\nu:\widehat{G}\to \mathbb{R}$ is regular if, with $d=\mathrm{rk}(\nu)$, for all $\kappa\in\mathbb{R}$ with $\left\lvert \kappa\right\rvert\leq 1/100d$ we have
\[(1-100 d\left\lvert \kappa\right\rvert)\leq \frac{\left\lvert \mathrm{Bohr}((1+\kappa)\nu)\right\rvert}{\left\lvert \mathrm{Bohr}(\nu)\right\rvert}\leq(1+ 100 d\left\lvert \kappa\right\rvert)\]
\end{definition}

n25291.content:
\begin{lemma}
\label{bohr-regularity}
\uses{bohr-reg-def}
\lean{BohrSet.regularity}
\leanok
For any $\nu:\widehat{G}\to \mathbb{R}$ there exists $\rho\in[\frac{1}{2},1]$ such that $\rho\cdot \nu$ is regular.
\end{lemma}

n25293.content:
\begin{lemma}
\label{reg-conv}
\uses{bohr-reg-def}
If $B$ is a regular Bohr set of rank $d$ and $\mu:G\to\mathbb{R}_{\geq 0}$ is supported on $B_\rho$, with $\rho \in (0,1)$, then
\[ \lVert  \mu_B*\mu - \mu_B \rVert_{1} \ll \rho d\lVert \mu\rVert_1. \]
\end{lemma}

n25295.content:
\begin{lemma}
\label{bohr-majorise}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds.  Let $B$ be a regular Bohr set of rank $d$ and $L\geq 1$ be any integer. If $\nu:G\to\mathbb{R}_{\geq 0}$ is supported on $L B_\rho$, where $\rho \leq c/Ld$, and $\lVert \nu\rVert_1=1$, then
\[\mu_B \leq 2\mu_{B_{1+L\rho}}\ast \nu.\]
\end{lemma}

n25297.content:
\begin{lemma}
\label{bourgain-trick}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let $B$ be a regular Bohr set of rank $d$, suppose $A\subseteq B$ has density $\alpha$, let $\epsilon>0$, and suppose $B',B''\subseteq B_\rho$ where $\rho\leq c\alpha\epsilon/d$. Then either
\begin{enumerate}
\item there is some translate $A'$ of $A$ such that $\left\lvert A'\cap B'\right\rvert\geq (1-\epsilon)\alpha\left\lvert B'\right\rvert$ and $\left\lvert A'\cap B''\right\rvert\geq (1-\epsilon)\alpha \left\lvert B''\right\rvert$, or
\item $\lVert 1_{A}\ast \mu_{B'}\rVert_\infty\geq (1+\epsilon/2)\alpha$, or
\item $\lVert 1_{A}\ast \mu_{B''}\rVert_\infty \geq (1+\epsilon/2)\alpha$.
\end{enumerate}
\end{lemma}

n25299.content:
\begin{theorem}
\label{th-ap-int}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let $\epsilon>0$ and $B,B'\subseteq G$ be regular Bohr sets of rank $d$. Suppose that $A_1\subseteq B$ with density $\alpha_1$ and $A_2$ is such that there exists $x$ with $A_2\subseteq B'-x$ with density $\alpha_2$. Let $S$ be any set with $\left\lvert S\right\rvert\leq 2\left\lvert B\right\rvert$. There is a regular Bohr set $B''\subseteq B'$ of rank at most
\[d+O_\epsilon(\mathcal{L}{\alpha_1}^3\mathcal{L}{\alpha_2})\]
and size
\[\left\lvert B''\right\rvert\geq \exp(-O_\epsilon(d\mathcal{L}{\alpha_1\alpha_2/d}+\mathcal{L}{\alpha_1}^3\mathcal{L}{\alpha_2}\mathcal{L}{\alpha_1\alpha_2/d}))\left\lvert B'\right\rvert\]
such that
\[\left\lvert \langle \mu_{B'}\ast \mu_{A_1}\circ \mu_{A_2},1_{S}\rangle-\langle \mu_{A_1}\circ \mu_{A_2},1_{S}\rangle\right\rvert\leq \epsilon.\]
\end{theorem}

n25301.content:
\begin{proposition}
\label{Lp-orth}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let $\epsilon >0$ and $p \geq 2$ be an integer. Let $B \subseteq G$ be a regular Bohr set and $A\subseteq B$ with relative density $\alpha$. Let $\nu : G \to \mathbb{R}_{\geq 0}$ be supported on $B_\rho$, where $\rho \leq c\epsilon\alpha/\rk(B)$, such that $\lVert \nu\rVert_1=1$ and $\widehat{\nu}\geq 0$. If
    \[ \lVert (\mu_A-\mu_B) \circ (\mu_{A}-\mu_B)\rVert_{p(\nu)} \geq \epsilon\, \mu(B)^{-1}, \]
    then there exists $p'\ll_\epsilon p$ such that
    \[ \lVert  \mu_{A}\circ \mu_{A}\rVert_{p'(\nu)} \geq \left(1+\tfrac{1}{4}\epsilon\right) \mu(B)^{-1}. \]
\end{proposition}

n25303.content:
\begin{proposition}
\label{pos-def-measures}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let $p \geq 2$ be an even integer. Let $f : G \to \mathbb{R}$, let $B \subseteq G$ and $B', B'' \subseteq B_{c/\rk(B)}$ all be regular Bohr sets. Then
\[ \lVert  f\circ f \rVert_{p(\mu_{B'}\circ \mu_{B'}\ast \mu_{B''}\circ \mu_{B''})} \geq \tfrac{1}{2} \lVert f*f\rVert_{p(\mu_B)}. \]
\end{proposition}

n25305.content:
\begin{proposition}
\label{hoelder-lifting}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let $\epsilon >0$. Let $B \subseteq G$ be a regular Bohr set and $A\subseteq B$ with relative density $\alpha$, and let $B' \subseteq B_{c\epsilon\alpha/\rk(B)}$ be a regular Bohr set and $C\subseteq B'$ with relative density $\gamma$. Either
\begin{enumerate}
\item $\left\lvert  \langle \mu_A*\mu_A, \mu_{C} \rangle - \mu(B)^{-1} \right\rvert \leq \epsilon \mu(B)^{-1}$ or
\item there is some $p \ll\mathcal{L}{\gamma}$ such that $\lVert  (\mu_A-\mu_B)*(\mu_A-\mu_B)\rVert_{p(\mu_{B'})} \geq \tfrac{1}{2}\epsilon \mu(B)^{-1}$.
\end{enumerate}
\end{proposition}

n25307.content:
\begin{proposition}
\label{prop-it}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let $\epsilon>0$ and $p,k\geq 1$ be integers such that $(k,\left\lvert G\right\rvert)=1$. Let $B,B',B''\subseteq G$ be regular Bohr sets of rank $d$ such that $B''\subseteq B'_{c/d}$ and $A\subseteq B$ with relative density $\alpha$. If
    \[ \lVert  \mu_{A}\circ \mu_{A}\rVert_{p(\mu_{k\cdot B'}\circ\mu_{k\cdot B'}\ast \mu_{k\cdot B''}\circ \mu_{k\cdot B''})} \geq \left(1+\epsilon\right) \mu(B)^{-1},\]
    then there is a regular Bohr set $B'''\subseteq B''$ of rank at most
    \[\rk(B''')\leq d+O_{\epsilon}(\mathcal{L}{\alpha}^4p^4)\]
    and size
    \[\left\lvert B'''\right\rvert\geq \exp(-O_{\epsilon}(dp\mathcal{L}{\alpha/d}+\mathcal{L}{\alpha}^5p^5))\left\lvert B''\right\rvert\]
    such that
    \[ \lVert  \mu_{B'''}*\mu_A \rVert_\infty \geq (1+c\epsilon)\mu(B)^{-1}. \]
\end{proposition}

n25309.content:
\begin{theorem}
\label{flat-on-bohr}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let ${\epsilon,\delta\in (0,1)}$ and $p,k\geq 1$ be integers such that $(k,\left\lvert G\right\rvert)=1$. For any $A\subseteq G$ with density $\alpha$ there is a regular Bohr set $B$ with
\[ d=\rk(B) =O_{\epsilon}\left(\mathcal{L}{\alpha}^5p^4\right) \quad\text{and}\quad \left\lvert B\right\rvert\geq \exp\left(-O_{\epsilon,\delta}(\mathcal{L}{\alpha}^6p^5\mathcal{L}{\alpha/p})\right)\left\lvert G\right\rvert \]
and some $A'\subseteq (A-x)\cap B$ for some $x \in G$ such that
\begin{enumerate}
\item $\left\lvert A'\right\rvert\geq (1-\epsilon)\alpha\left\lvert B\right\rvert$,
\item $\left\lvert A'\cap B'\right\rvert\geq (1-\epsilon)\alpha\left\lvert B'\right\rvert$, where $B'=B_{\rho}$ is a regular Bohr set with ${\rho\in (\tfrac{1}{2},1)\cdot c\delta\alpha/d}$, and
\item
\[\lVert \mu_{A'}\circ \mu_{A'}\rVert_{p(\mu_{k\cdot B''}\circ \mu_{k\cdot B''}\ast \mu_{k\cdot B'''}\circ \mu_{k\cdot B'''})} <(1+ \epsilon)\mu(B)^{-1},\]
for any regular Bohr sets $B'' = B'_{\rho'}$ and $B'''=B''_{\rho''}$ satisfying ${\rho',\rho''\in(\frac{1}{2},1)\cdot c\delta\alpha/d}$.
\end{enumerate}
\end{theorem}

n25311.content:
\begin{theorem}
\label{th-int-gen}
\uses{bohr-reg-def}
There is a constant $c>0$ such that the following holds. Let $\delta,\epsilon\in (0,1)$, let $p \geq 1$ and let $k$ be a positive integer such that $(k,\left\lvert G\right\rvert)=1$. There is a constant $C=C(\epsilon,\delta,k)>0$ such that the following holds.

For any finite abelian group $G$ and any subset $A\subseteq G$ with $\left\lvert A\right\rvert=\alpha \left\lvert G\right\rvert$ there exists a regular Bohr set $B$ with
\[\rk(B)\leq Cp^4\log(2/\alpha)^5\]
and
\[\left\lvert B\right\rvert\geq \exp\left(-Cp^5\log(2p/\alpha)\log(2/\alpha)^6\right)\left\lvert G\right\rvert\]
and $A' \subseteq (A-x)\cap B$ for some $x\in G$ such that
\begin{enumerate}
\item $\left\lvert A'\right\rvert\geq (1-\epsilon)\alpha \left\lvert B\right\rvert$,
\item $\left\lvert A'\cap B'\right\rvert\geq (1-\epsilon)\alpha\left\lvert B'\right\rvert$, where $B'=B_{\rho}$ is a regular Bohr set with $\rho\in (\tfrac{1}{2},1)\cdot c\delta\alpha/dk$, and
\item
\[\lVert (\mu_{A'}-\mu_B)\ast (\mu_{A'}- \mu_B)\rVert_{p(\mu_{k\cdot B'})} \leq \epsilon\frac{\left\lvert G\right\rvert}{\left\lvert B\right\rvert}.\]
\end{enumerate}
\end{theorem}

n25313.content:
\begin{theorem}\label{main-int-count}
If $A\subseteq \{1,\ldots,N\}$ has size $\left\lvert A\right\rvert=\alpha N$, then $A$ contains at least
\[\exp(-O(\mathcal{L}{\alpha}^{12}))N^2\]
many three-term arithmetic progressions.
\end{theorem}

n25315.content:
\begin{theorem}[Integer case]
  \label{int}
  \uses{}
  \lean{int}
